static std::string read(const std::filesystem::path& path) {
  std::string value; assert(SUCCEEDED(document::read(path, value))); return value;
}
static void put(const std::filesystem::path& path, const std::string& value) {
  document::File file(CreateFileW(path.c_str(), GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr));
  assert(file.get() != INVALID_HANDLE_VALUE);
  DWORD count = 0; assert(WriteFile(file.get(), value.data(), static_cast<DWORD>(value.size()), &count, nullptr) && count == value.size());
}
static unsigned definitions(const std::string& text, const std::string& key) {
  unsigned count = 0;
  for (size_t start = 0; start < text.size();) {
    auto end = text.find('\n', start); if (end == std::string::npos) { end = text.size(); }
    const auto line = document::parse(text.substr(start, end - start));
    if (line.valid && line.key == key) { ++count; }
    start = end + 1;
  }
  return count;
}
